package com.ruoyi.web.controller.shop;
import java.util.*;import java.time.*;import com.alibaba.fastjson2.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Lazy;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.ruoyi.web.controller.shop.ShopService.*;
@Service public class ShopDelivery {
 @Autowired @Lazy ShopService s;@Autowired ShopWarehouse warehouse;
 public JSONObject settings(){return JSON.parseObject(str(s.one("select content from shop_config where config_key='delivery'").get("content")));}
 public void quote(JSONObject b,Map<String,Object> q){JSONObject config=settings(),snapshot=new JSONObject();String method=str(b.get("deliveryMethod"));if(method.isEmpty())method="express";check(config.getJSONArray("methods").contains(method),"该配送方式未开放");long goods=number(q.get("amount")),fee=0,quantity=0;for(Object obj:(List<?>)q.get("items"))quantity+=((JSONObject)obj).getLongValue("quantity");snapshot.put("method",method);if("pickup".equals(method)){String pointId=str(b.get("pickupPoint"));JSONObject point=null;for(Object obj:config.getJSONArray("points")){JSONObject p=JSON.parseObject(JSON.toJSONString(obj));if(pointId.equals(p.getString("id")))point=p;}check(point!=null,"请选择自提门店");snapshot.put("point",point);}else{JSONObject address=b.getJSONObject("address");String location=address==null?"":str(address.get("province"))+str(address.get("city"))+str(address.get("address"));JSONObject selected=null,fallback=null;for(Object obj:config.getJSONArray("rules")){JSONObject rule=JSON.parseObject(JSON.toJSONString(obj));if(!method.equals(rule.getOrDefault("method","express")))continue;for(Object area:rule.getJSONArray("regions")){if("*".equals(str(area)))fallback=rule;else if(!location.isEmpty()&&location.contains(str(area)))selected=rule;}}if(selected==null)selected=fallback;check(selected!=null,"该收货地区尚未配置配送服务，请选择其他地址或联系客服");fee=selected.getLongValue("firstFee")+Math.max(0,(quantity-selected.getLongValue("first")+selected.getLongValue("next")-1)/selected.getLongValue("next"))*selected.getLongValue("nextFee")+selected.getLongValue("remoteFee");if(selected.getLongValue("freeAmount")>0&&goods>=selected.getLongValue("freeAmount"))fee=0;snapshot.put("rule",selected);}
 snapshot.put("fee",fee);snapshot.put("notice",config.get("notice"));q.put("goodsAmount",goods);q.put("shippingFee",fee);q.put("delivery",snapshot);q.put("amount",goods+fee);}
 public void reserve(long oid,Map<String,Object> q){JSONObject snapshot=(JSONObject)q.get("delivery");String method=snapshot.getString("method"),code="pickup".equals(method)?String.format(Locale.ROOT,"%08d",new java.security.SecureRandom().nextInt(100000000)):null;s.jdbc().update("insert into shop_delivery_order(order_id,method,fee,snapshot_json,pickup_code) values(?,?,?,?,?)",oid,method,q.get("shippingFee"),snapshot.toJSONString(),code);s.jdbc().update("update shop_order set shipping_amount=? where id=?",q.get("shippingFee"),oid);}
 public boolean pickup(long oid){return s.jdbc().queryForObject("select count(*) from shop_delivery_order where order_id=? and method='pickup'",Long.class,oid)>0;}
 public Map<String,Object> info(long uid,long oid){s.companyOrder(uid,oid,"view",false);List<Map<String,Object>> rows=s.jdbc().queryForList("select * from shop_delivery_order where order_id=?",oid);Map<String,Object> r=rows.isEmpty()?new HashMap<>():rows.get(0);r.put("traces",s.jdbc().queryForList("select t.id,t.shipment_id,t.occurred_at,t.note from shop_delivery_trace t join shop_shipment p on p.id=t.shipment_id where p.order_id=? order by t.occurred_at,t.id",oid));return r;}
 public long refundFee(JSONObject b,Map<String,Object> o,JSONArray selected,long remainingQty){if(!b.getBooleanValue("refundShipping"))return 0;check("merchant".equals(b.getString("reasonCode")),"整单商家原因退款可申请退原运费，其他补退由财务有据处理");long selectedQty=0;for(Object obj:selected)selectedQty+=JSON.parseObject(JSON.toJSONString(obj)).getLongValue("quantity");check(selectedQty==remainingQty,"部分商品退款不自动退运费");return number(o.get("shipping_amount"))-number(o.get("refunded_shipping_amount"));}
 public void refund(Map<String,Object> c,Map<String,Object> o){long fee=number(c.get("shipping_amount"));if(fee==0)return;check(fee<=number(o.get("shipping_amount"))-number(o.get("refunded_shipping_amount")),"运费退款超过剩余可退额");s.jdbc().update("update shop_order set refunded_shipping_amount=refunded_shipping_amount+? where id=?",fee,o.get("id"));}
 @Transactional public void supplement(long oid,JSONObject b,String who){Map<String,Object> o=s.one("select * from shop_order where id=? for update",oid);String key=str(b.get("requestKey")),note=str(b.get("note")).trim();check(key.matches("[a-zA-Z0-9_-]{8,80}"),"请重新提交运费补退");long fee=integer(b.get("amount"),1,100000000,"请填写运费补退金额（分）");List<Map<String,Object>> old=s.jdbc().queryForList("select amount,reason from shop_case where order_id=? and shipping_request_key=?",oid,key);if(!old.isEmpty()){check(number(old.get(0).get("amount"))==fee&&("运费补退："+note).equals(old.get(0).get("reason")),"重复请求内容不同，请刷新后处理");return;}check(o.get("paid_at")!=null&&fee<=number(o.get("shipping_amount"))-number(o.get("refunded_shipping_amount")),"补退金额超过已收且尚未退回的运费");check(note.length()>=2&&note.length()<=300,"请填写补退依据");check(s.jdbc().queryForObject("select count(*) from shop_case where order_id=? and status not in ('refunded','completed','rejected')",Long.class,oid)==0,"请先完成正在处理的售后");s.jdbc().update("insert into shop_case(order_id,member_id,type,status,items_json,amount,reason,shipping_amount,shipping_request_key) values(?,?,'refund','pending','[]',?,?,?,?)",oid,o.get("member_id"),fee,"运费补退："+note,fee,key);s.event("order",oid,"创建有据运费补退申请，等待财务处理",who);}
 @Transactional public void prepare(long oid,String who){Map<String,Object> o=s.one("select * from shop_order where id=? for update",oid);check("paid".equals(o.get("status"))&&pickup(oid),"仅已付款自提单可登记备货完成");s.jdbc().update("update shop_delivery_order set pickup_status='ready' where order_id=? and pickup_status='pending'",oid);s.event("order",oid,"自提商品备货完成",who);}
 @Transactional public void collect(String no,String code,String who){Map<String,Object> first=s.one("select id,member_id from shop_order where order_no=?",no);s.one("select id from shop_member where id=? for update",first.get("member_id"));long oid=number(first.get("id"));Map<String,Object> o=s.one("select * from shop_order where id=? for update",oid),d=s.one("select * from shop_delivery_order where order_id=? and method='pickup' for update",oid);check(str(d.get("pickup_code")).equals(code),"自提码不正确，请核对客户出示的信息");if("collected".equals(d.get("pickup_status")))return;check("paid".equals(o.get("status"))&&"ready".equals(d.get("pickup_status")),"自提订单尚未备货完成或已关闭");check(s.jdbc().queryForObject("select count(*) from shop_case where order_id=? and status not in ('refunded','completed','rejected')",Long.class,oid)==0,"请先处理正在进行的售后");JSONArray items=new JSONArray();for(Map<String,Object> a:warehouse.allocations(oid)){long qty=number(a.get("reserved"));if(qty<=0)continue;Map<String,Object> line=s.one("select id,name,spec from shop_order_item where order_id=? and product_id=?",oid,a.get("product_id"));JSONObject i=new JSONObject(line);i.put("quantity",qty);items.add(i);}check(!items.isEmpty(),"没有待自提商品");JSONObject point=JSON.parseObject(str(d.get("snapshot_json"))).getJSONObject("point");s.campaignShip(oid);long wid=warehouse.ship(oid,point.getLongValue("warehouseId"),items,who);s.jdbc().update("insert into shop_shipment(order_id,carrier,tracking,items_json,warehouse_id,received,received_at) values(?,'门店自提','现场核销',?,?,1,now())",oid,items.toJSONString(),wid);s.jdbc().update("update shop_delivery_order set pickup_status='collected' where order_id=?",oid);s.jdbc().update("update shop_order set status='completed' where id=?",oid);s.orderReceived(oid);s.event("order",oid,"客户出示自提码，现场核销完成",who);}
 @Transactional public void trace(long shipment,JSONObject b,String who){Map<String,Object> p=s.one("select order_id,created_at from shop_shipment where id=?",shipment);check(!pickup(number(p.get("order_id"))),"自提订单无需填写物流轨迹");String note=str(b.get("note")).trim();check(note.length()>=2&&note.length()<=500,"请填写真实物流记录及来源");java.sql.Timestamp when;try{when=java.sql.Timestamp.valueOf(str(b.get("time")).replace('T',' '));}catch(Exception e){throw new IllegalArgumentException("请填写实际发生时间");}check(when.getTime()<=System.currentTimeMillis()+300000&&when.getTime()>=timestamp(p.get("created_at")).getTime(),"轨迹时间应在发货后且不能晚于当前时间");s.jdbc().update("insert into shop_delivery_trace(shipment_id,occurred_at,note,operator_name) values(?,?,?,?)",shipment,when,note,who);s.event("order",number(p.get("order_id")),"人工登记实际物流轨迹",who);}
 @Transactional public void save(JSONObject b,String who){JSONArray methods=b.getJSONArray("methods"),rules=b.getJSONArray("rules"),points=b.getJSONArray("points");check(methods!=null&&!methods.isEmpty(),"至少开启一种配送方式");for(Object method:methods)check(Arrays.asList("express","freight","local","pickup").contains(str(method)),"配送方式不正确");if(points==null)points=new JSONArray();if(rules==null)rules=new JSONArray();check(rules.size()<=100&&points.size()<=100,"配送规则或门店最多100项");if(methods.contains("pickup"))check(!points.isEmpty(),"开启自提前请配置门店");for(Object obj:rules){JSONObject r=JSON.parseObject(JSON.toJSONString(obj));check(Arrays.asList("express","freight","local").contains(str(r.getOrDefault("method","express"))),"请选择运费规则对应配送方式");JSONArray areas=r.getJSONArray("regions");check(areas!=null&&!areas.isEmpty()&&areas.size()<=100,"请填写配送地区");for(Object a:areas)check(str(a).length()>=1&&str(a).length()<=60,"地区名称不正确");integer(r.get("first"),1,10000,"首件数量须为正整数");integer(r.get("next"),1,10000,"续件数量须为正整数");for(String k:Arrays.asList("firstFee","nextFee","remoteFee","freeAmount"))integer(r.get(k),0,100000000,"金额应为非负整数分");}Set<String> ids=new HashSet<>();for(Object obj:points){JSONObject p=JSON.parseObject(JSON.toJSONString(obj));check(str(p.get("id")).matches("[A-Za-z0-9_-]{1,40}")&&ids.add(p.getString("id")),"门店标识不能重复");check(str(p.get("name")).length()>0&&str(p.get("name")).length()<=80&&str(p.get("address")).length()>=5&&str(p.get("address")).length()<=400,"请填写门店名称与详细地址");s.one("select id from shop_warehouse where id=? and enabled=1",p.getLongValue("warehouseId"));}JSONObject clean=new JSONObject();clean.put("methods",methods);clean.put("rules",rules);clean.put("points",points);String notice=str(b.get("notice"));check(notice.length()<=500,"配送说明最多500字");clean.put("notice",notice);s.jdbc().update("update shop_config set content=? where config_key='delivery'",clean.toJSONString());s.event("delivery",0,"更新新订单配送规则",who);}
}
